// SI-generated: this file was generated by Claude Code (Anthropic, SI tool) and reviewed by the team.
// 多尺度地圖：EVA 現場（HiRISE 2 m）外圍接上 Gale 撞擊坑區域（MOLA 463 m），再往外是整顆火星（MOLA）。
// 所有資料都在 public/data/ 打包進網頁，離線可用。
import * as THREE from 'three';

const R_MARS = 3396190; // m（與 HiRISE / MOLA 投影相同的球半徑）
const DEG = Math.PI / 180;

async function loadI16(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url}: ${res.status}`);
  return new Int16Array(await res.arrayBuffer());
}

/** 經緯度 → 現場的公尺座標（等距圓柱投影，原點 = 現場西南角）。 */
export function geoToSite(geo, lat, lon) {
  return { x: (lon - geo.lon_min) * DEG * R_MARS, y: (lat - geo.lat_min) * DEG * R_MARS };
}

/**
 * Gale 區域地形 mesh，放在現場周圍；現場範圍內的頂點壓低，避免和高解析 mesh 重疊閃爍。
 * toV(x, y, z) 是 main.js 的座標轉換。
 */
export async function buildRegion(geo, toV, siteW, siteH) {
  const meta = await (await fetch('data/region/gale.json')).json();
  const z = await loadI16('data/region/gale.i16');
  const { width: w, height: h } = meta;
  const geom = new THREE.PlaneGeometry(1, 1, w - 1, h - 1);
  const pos = geom.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const lo = new THREE.Color('#3b1a0e'), hi = new THREE.Color('#c7865a'), c = new THREE.Color();
  let zmin = Infinity, zmax = -Infinity;
  for (const v of z) if (v > -30000) { zmin = Math.min(zmin, v); zmax = Math.max(zmax, v); }
  for (let r = 0; r < h; r++) {
    for (let col = 0; col < w; col++) {
      const k = r * w + col, j = h - 1 - r; // 頂點列 0 = 北；資料列 0 = 南
      const lat = meta.lat_min + ((j + 0.5) / h) * (meta.lat_max - meta.lat_min);
      const lon = meta.lon_min + ((col + 0.5) / w) * (meta.lon_max - meta.lon_min);
      const p = geoToSite(geo, lat, lon);
      let zz = z[j * w + col];
      const inside = p.x > -600 && p.x < siteW + 600 && p.y > -600 && p.y < siteH + 600;
      if (inside) zz -= 80;
      const v = toV(p.x, p.y, zz);
      pos.setXYZ(k, v.x, v.y, v.z);
      c.copy(lo).lerp(hi, (z[j * w + col] - zmin) / (zmax - zmin || 1));
      colors.set([c.r, c.g, c.b], k * 3);
    }
  }
  geom.computeVertexNormals();
  geom.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  const mesh = new THREE.Mesh(geom, new THREE.MeshLambertMaterial({ vertexColors: true }));
  mesh.visible = false;
  return { mesh, meta };
}

/** 整顆火星：球面依 MOLA 高程位移（誇張 12 倍），標出現場位置。單位：公里。 */
export async function buildGlobe(siteLat, siteLon) {
  const meta = await (await fetch('data/global/mars.json')).json();
  const z = await loadI16('data/global/mars.i16');
  const { width: w, height: h } = meta;
  const R = 3396.19, EX = 12;
  const geom = new THREE.SphereGeometry(R, 720, 360);
  const pos = geom.attributes.position, uv = geom.attributes.uv;
  const colors = new Float32Array(pos.count * 3);
  const ramp = ['#1d1f3a', '#5a2a1a', '#a4572f', '#d79a68', '#f2e3cf'].map((s) => new THREE.Color(s));
  const c = new THREE.Color(), n = new THREE.Vector3();
  for (let k = 0; k < pos.count; k++) {
    // SphereGeometry 的 u 從 −x 方向開始繞；用 uv 換算經緯度
    const u = uv.getX(k), vv = uv.getY(k);
    const lon = u * 360 - 180, lat = vv * 180 - 90;
    const col = Math.min(w - 1, Math.max(0, Math.floor(((lon + 180) / 360) * w)));
    const row = Math.min(h - 1, Math.max(0, Math.floor(((90 - lat) / 180) * h)));
    let e = z[row * w + col];
    if (e < -30000) e = 0;
    n.fromBufferAttribute(pos, k).normalize();
    pos.setXYZ(k, n.x * (R + (e / 1000) * EX), n.y * (R + (e / 1000) * EX), n.z * (R + (e / 1000) * EX));
    const t = Math.min(Math.max((e + 8000) / 20000, 0), 1) * (ramp.length - 1);
    const i = Math.min(Math.floor(t), ramp.length - 2);
    c.copy(ramp[i]).lerp(ramp[i + 1], t - i);
    colors.set([c.r, c.g, c.b], k * 3);
  }
  geom.computeVertexNormals();
  geom.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  const globe = new THREE.Group();
  const material = new THREE.MeshLambertMaterial({ vertexColors: true });
  globe.add(new THREE.Mesh(geom, material));
  // Viking 彩色鑲嵌圖（組員的資料）：圖片經度 0..360，球的 u 從 −180 開始 → 平移半圈
  try {
    const tex = await new THREE.TextureLoader().loadAsync('data/global/satellite.jpg');
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.RepeatWrapping;
    tex.offset.x = 0.5;
    material.map = tex;
    material.vertexColors = false;
    material.needsUpdate = true;
  } catch { /* 沒有衛星圖就用高程配色 */ }
  // 現場標記（SphereGeometry: x = −cos(lon')sin(θ)…，用同樣的 uv 規則換算）
  const phi = ((siteLon + 180) / 360) * Math.PI * 2, theta = ((90 - siteLat) / 180) * Math.PI;
  const dir = new THREE.Vector3(-Math.cos(phi) * Math.sin(theta), Math.cos(theta), Math.sin(phi) * Math.sin(theta));
  const pin = new THREE.Mesh(new THREE.ConeGeometry(25, 160, 12), new THREE.MeshBasicMaterial({ color: '#4dd6ff' }));
  pin.position.copy(dir.clone().multiplyScalar(R + 90));
  pin.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir.clone().negate());
  globe.add(pin);
  globe.visible = false;
  return { globe, siteDir: dir, R };
}
